mapper.select:
SELECT r.id, r.event_time, CAST(r.normalized_payload AS CHAR) normalized_payload
FROM ingest_record r
JOIN ingest_batch b ON b.id=r.batch_id AND b.feature_contract_version=#{contract}
WHERE r.asset_id=#{assetId} AND r.event_time >= #{from} AND r.event_time <= #{to}
  AND r.quality_status='accepted'
ORDER BY r.event_time, r.id
LIMIT #{limit}
FOR SHARE

SELECT r.event_time FROM detection_alert da JOIN ingest_record r ON r.id=da.ingest_record_id
WHERE da.detection_rule_id=#{ruleId} AND da.alert_type='rule' AND r.asset_id=#{assetId}
  AND r.event_time >= #{from} AND r.event_time <= #{to}
ORDER BY r.event_time
FOR SHARE
